@Bean
public MongoDatabase mongoDatabase(MongoClient mongoClient, Config config) throws ClassNotFoundException {
    List<Convention> conventions = unmodifiableList(asList(
        CLASS_AND_PROPERTY_CONVENTION,
        ANNOTATION_CONVENTION,
        OBJECT_ID_GENERATORS,
        new IgnoreNullEmptyConvention()
    ));

    PojoCodecProvider.Builder codecBuilder = PojoCodecProvider.builder().automatic(true);
    List<String> configClasses = config.getConfigList("repo.cache").stream()
            .map(val -> val.getString("valueClass"))
            .collect(Collectors.toList());
    configClasses.add("life.arogya.core.domain.fhir.type.CodeableConcept");
    configClasses.add("life.arogya.core.domain.fhir.type.Extension");

    for (String clazz : configClasses) {
        Class<?> entity = Class.forName(clazz);
        ClassModelBuilder<?> modelBuilder = ClassModel.builder(entity);
        // Filter JsonIgnore attributes from Mongo persistence
        Arrays.stream(entity.getDeclaredFields())
              .filter(f -> f.isAnnotationPresent(JsonIgnore.class) && !f.getName().equals("mongoId"))
              .forEach(f -> modelBuilder.removeProperty(f.getName()));
        codecBuilder.register(modelBuilder.conventions(conventions).build());
    }

    CodecProvider pojoProvider = codecBuilder.conventions(conventions).build();
    CodecRegistry registry = fromRegistries(getDefaultCodecRegistry(), fromProviders(pojoProvider));
    return mongoClient.getDatabase(config.getString("mongodb.name")).withCodecRegistry(registry);
}
